sealed class BException(message: String): kotlin.Exception(message) {
        
        class RemoteStorageException(message: String) : BException(message)
        
        class AssetLoadFail(message: String) : BException(message)
        
        class AssetNotFound(message: String) : BException(message)
        
        class PlaylistNotFound(message: String) : BException(message)
        
        class MusicNotFound(message: String) : BException(message)
        
        class DbException(message: String) : BException(message)
        
        class IoException(message: String) : BException(message)
        
        class JsonException(message: String) : BException(message)
        
        class OrderKeyException(message: String) : BException(message)
        
        class CustomException(message: String) : BException(message)
        
        class AnyHowException(message: String) : BException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<BException> {
        override fun lift(error_buf: RustBuffer.ByValue): BException = FfiConverterTypeBError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeBError : FfiConverterRustBuffer<BException> {
    override fun read(buf: ByteBuffer): BException {
        
            return when(buf.getInt()) {
            1 -> BException.RemoteStorageException(FfiConverterString.read(buf))
            2 -> BException.AssetLoadFail(FfiConverterString.read(buf))
            3 -> BException.AssetNotFound(FfiConverterString.read(buf))
            4 -> BException.PlaylistNotFound(FfiConverterString.read(buf))
            5 -> BException.MusicNotFound(FfiConverterString.read(buf))
            6 -> BException.DbException(FfiConverterString.read(buf))
            7 -> BException.IoException(FfiConverterString.read(buf))
            8 -> BException.JsonException(FfiConverterString.read(buf))
            9 -> BException.OrderKeyException(FfiConverterString.read(buf))
            10 -> BException.CustomException(FfiConverterString.read(buf))
            11 -> BException.AnyHowException(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: BException): ULong {
        return 4UL
    }

    override fun write(value: BException, buf: ByteBuffer) {
        when(value) {
            is BException.RemoteStorageException -> {
                buf.putInt(1)
                Unit
            }
            is BException.AssetLoadFail -> {
                buf.putInt(2)
                Unit
            }
            is BException.AssetNotFound -> {
                buf.putInt(3)
                Unit
            }
            is BException.PlaylistNotFound -> {
                buf.putInt(4)
                Unit
            }
            is BException.MusicNotFound -> {
                buf.putInt(5)
                Unit
            }
            is BException.DbException -> {
                buf.putInt(6)
                Unit
            }
            is BException.IoException -> {
                buf.putInt(7)
                Unit
            }
            is BException.JsonException -> {
                buf.putInt(8)
                Unit
            }
            is BException.OrderKeyException -> {
                buf.putInt(9)
                Unit
            }
            is BException.CustomException -> {
                buf.putInt(10)
                Unit
            }
            is BException.AnyHowException -> {
                buf.putInt(11)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




